// Replays every generated case through the Rust port and compares the results
// with the C++ JoinStringT output.
#[test]
fn matches_cpp_join_string_template() {
    use join_string::{join_string, join_string16};

    assert_eq!(JOIN_CASES.len(), 150);
    for (i, c) in JOIN_CASES.iter().enumerate() {
        assert_eq!(join_string(c.parts, c.sep), c.expected, "JoinString case {i}");
    }
    for (i, c) in JOIN_CASES16.iter().enumerate() {
        assert_eq!(join_string16(c.parts, c.sep), c.expected, "JoinString16 case {i}");
    }
}
